# Flood comps of free cells (0/3), 8-connected; count distinct 2s each comp touches (via adjacency). If >=2 -> whole comp becomes 1.
def f(I, conn8=True):
    H_,W_=len(I),len(I[0]); res=[row[:] for row in I]
    D=DIRS8 if conn8 else DIRS4
    seen=set(); 
    for a in range(H_):
